import React from 'react';
import { isElement } from 'react-is';

import { HeatmapSeries } from '../slots/HeatmapSeries.js';
import { XAxis } from '../slots/XAxis.js';
import type {
  XYChartAxisProps,
  XYChartHeatmapSeriesProps,
  XYChartSlots,
} from '../types/xy-chart.js';

/**
 * Extracts XY chart's slots
 */
export const iterateSlots = (children: React.ReactNode): XYChartSlots => {
  const slots: XYChartSlots = {
    heatmapSeries: [],
    axes: [],
  };

  React.Children.forEach(children, (child) => {
    if (isElement(child)) {
      switch (child.type) {
        case HeatmapSeries: {
          const data = child.props as XYChartHeatmapSeriesProps;
          slots.heatmapSeries = [...slots.heatmapSeries, data];
          break;
        }
        case XAxis: {
          const axis: XYChartAxisProps = child.props;
          slots.axes = [...slots.axes, axis];
          break;
        }
      }
    }
  });

  return slots;
};
